contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function runBurnSupplyCheck(uint256 v) public {
        // owner (deployer of C) burns v tokens; must have enough balance
        require(v <= c.balanceOf(msg.sender), "need balance");
        uint256 tsBefore = c.totalSupply();
        c.burn(v);
        uint256 tsAfter = c.totalSupply();
        assert(tsAfter == tsBefore - v);
    }
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function test(uint256 v) public {
    require(v > 0);
    uint256 s0 = c.totalSupply();
    c.burn(v);
    uint256 s1 = c.totalSupply();
    assert(s1 == s0 - v);
  }
  receive() external payable {}
  fallback() external payable {}
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function test(uint256 burnAmount) public {
    require(burnAmount > 0);
    bool reverted = false;
    // onlyOwner on burn means a non-owner call must fail on P, but succeeds on M
    // use a fresh attacker address: this contract is not the owner
    uint256 supplyBefore = c.totalSupply();
    // top-level state-changing call, revert observed via try not allowed -> use low-level call
    (bool ok, ) = address(c).call(abi.encodeWithSelector(c.burn.selector, burnAmount));
    reverted = !ok;
    assert(reverted && c.totalSupply() == supplyBefore);
  }
  receive() external payable {}
  fallback() external payable {}
}

