contract InvMutTest {
  C c;

  constructor(C _c) { c = _c; }

  function runFreezeTest(address target) public {
    require(target != msg.sender, "target must differ from caller");
    c.freezeAccount(target, true);
    assert(c.frozenAccount(target));
  }

  receive() external payable {}
  fallback() external payable {}
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function run(address target) public {
    (bool ok, ) = address(c).call(abi.encodeWithSelector(c.freezeAccount.selector, target, true));
    assert(!ok && !c.frozenAccount(target));
  }
}

